    """调用 python -m task_center，返回 (退出码, 解析后的 JSON 记录)。"""
    proc = subprocess.run(
        [sys.executable, "-m", "task_center", "--db", db or self.db, *args],
        cwd=str(PROJECT_ROOT),
        capture_output=True,
        text=True,
    )
